// Version A
class Customer {
  constructor(private id: string, private name: string, private address: string) {}
  changeAddress(newAddress: string) {
    if (newAddress.length === 0) throw new Error("invalid address");
    this.address = newAddress;
  }
  getContactInfo() { return `${this.name} <${this.address}>`; }
}

// Version B
type CustomerRecord = { id: string; name: string; address: string };
class CustomerService {
  changeAddress(c: CustomerRecord, newAddress: string) {
    if (newAddress.length === 0) throw new Error("invalid address");
    c.address = newAddress;
  }
  getContactInfo(c: CustomerRecord) { return `${c.name} <${c.address}>`; }
}
